import {abilityKeys,heavyName} from '../game/bindings.js';
export {heavyName};
/* Default labels for callers without a save; gameplay and teaching read saved bindings. */
export const FIXED_KEYS={settings:'o',menu:'escape',journal:'tab',map:'m',run:'r',fullscreen:'f',abilities:['1','2','3','4']};
export const keyLabel=k=>k===' '?'Space':k==='escape'?'Esc':k==='shift'?'Shift':k==='tab'?'Tab':String(k).toUpperCase();
export function controlRows(s){const b=s.settings.bindings;return [['Move',[b.up,b.left,b.down,b.right].map(keyLabel).join(' / ')+' or arrow keys'],['Run',keyLabel(b.run)],['Basic attack',keyLabel(b.attack)],['Heavy attack',keyLabel(b.heavy)],[heavyName(s),'Hold '+keyLabel(b.attack)+' > 0.5 s, then release'],['Dodge',keyLabel(b.dodge)],['Jump',keyLabel(b.jump)],['Abilities',abilityKeys(s).map(keyLabel).join(' / ')],['Interact',keyLabel(b.interact)],['Potion',keyLabel(b.potion)],['Map',keyLabel(b.map)],['Level map',keyLabel(b.localMap)],['Fast travel',keyLabel(b.travel)],['Journal',keyLabel(b.journal)],['Menu',keyLabel(b.menu)],['Settings',keyLabel(b.settings)],['Fullscreen',keyLabel(b.fullscreen)],['Map: play / home / stats / chapters','Enter / H / Tab / 1-3'],['Panels: select / activate / back','Tab / Enter or Space / Esc']];}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function controlsHTML(s,touch=false){if(touch)return touchControlsHTML(s);const b=s.settings.bindings,cap=k=>`<kbd>${escape(keyLabel(k))}</kbd>`,row=(label,keys,note='')=>`<div class="control-row"><span>${label}${note?`<small>${note}</small>`:''}</span><div class="control-keys">${keys.map(cap).join(' ')}</div></div>`,group=(name,rows)=>`<section class="control-group"><h3>${name}</h3>${rows}</section>`;return `<div class="controls-table controls-groups">${group('Move',row('Move',[b.up,b.left,b.down,b.right],'Arrow keys also move')+row('Run',[b.run],'Hold while moving · joystick rim on touch')+row('Jump',[b.jump],'Hop while exploring')+row('Interact',[b.interact],'Talk, use or search nearby'))}${group('Fight',row('Basic attack',[b.attack],'Tap for a quick strike')+row('Heavy attack',[b.heavy],`Instant ${heavyName(s)}`)+row(heavyName(s),[b.attack],`Hold ${escape(keyLabel(b.attack))} for half a second, then release`)+row('Dodge',[b.dodge],'Roll away from danger')+row('Potion',[b.potion],'Use your selected potion'))}${group('Abilities',[1,2,3,4].map(i=>row('Ability '+i,[b['ability'+i]])).join('')+'<p class="subtle">Use the abilities equipped on your action bar. Learn at the Library to unlock more.</p>')}${group('Menus',row('Map',[b.map],'Oakhaven in town; the world map elsewhere (it pauses a level)')+row('Level map',[b.localMap],'Inside a level: its own map')+row('Fast travel',[b.travel],'In Oakhaven or on the world map: go to a place you have visited')+row('Journal',[b.journal])+row('Menu',[b.menu])+row('Settings',[b.settings])+row('Fullscreen',[b.fullscreen]))}</div><p class="controls-navigation subtle">Inside panels: ${cap('tab')} select · ${cap('enter')} / ${cap(' ')} activate · ${cap('escape')} back. Map navigation uses the hints shown on the map.</p>`;}
export function controlsHUD(s){const b=s.settings.bindings;return [['Move',[b.up,b.left,b.down,b.right].map(keyLabel).join(' ')],['Run',b.run],['Jump',b.jump],['Attack',b.attack],[heavyName(s),'Hold '+keyLabel(b.attack)],['Dodge',b.dodge],['Interact',b.interact],['Map',b.map],['Menu',b.menu]].map(([a,k])=>`<span>${a} <kbd>${escape(a===heavyName(s)?k:keyLabel(k))}</kbd></span>`).join('');}

export function armourHintText(s,touch=false){return touch?`Armour! Hold and release Attack for a ${heavyName(s)}, or tap an ability button.`:`Armour! Break it with a ${heavyName(s)} (hold ${keyLabel(s.settings.bindings.attack)}, then release) or an ability (${abilityKeys(s).map(keyLabel).join(' / ')}).`;}

export function abilityNudgeText(a,slot,touch=false,s=null){return touch?`Tip: tap the glowing button for ${a.name}!`:`Tip: press ${keyLabel(s?abilityKeys(s)[slot]:FIXED_KEYS.abilities[slot])} for ${a.name}!`;}

/* Touch help names the controls actually visible on phones and tablets. */
function touchControlsHTML(s){const row=(label,note)=>`<div class="control-row"><span>${label}<small>${note}</small></span></div>`,group=(name,rows)=>`<section class="control-group"><h3>${name}</h3>${rows}</section>`;return `<div class="controls-table controls-groups">${group('Move',row('Move','Drag the joystick on the left.')+row('Run','Push the joystick to its rim.')+row('Jump','Tap the upward arrow.')+row('Interact','Walk close, then tap the hand button: Study, Talk, Open or another action.'))}${group('Fight',row('Basic attack','Tap Attack, the large sword button.')+row(heavyName(s),'Hold Attack for half a second, then release.')+row('Dodge','Tap the boot button to roll away.')+row('Potion','Tap the potion bottle.'))}${group('Abilities',row('Use a learned ability','Tap its icon beside Attack. Learn at the Library to unlock more.'))}${group('Menus',row('Map and Journal','Tap their buttons at the top right.')+row('Menu','Tap Menu to pause, view controls, open Settings or change fullscreen.')+row('World map','Tap a destination, then Play. Home returns to Oakhaven.')+row('Fast travel','Open the map, then Fast travel: go to any place you have visited. It is free.'))}</div><p class="controls-navigation subtle">Inside panels: tap buttons and swipe to scroll. Use Close or Back to return.</p>`;}
